mapper.select:
select al.id, al.actor_type as actorType, al.actor_user_id as actorUserId, al.subject_type as subjectType, al.subject_id as subjectId, al.action, al.reason, al.created_at as createdAt, su.user_name as actorUserName, su.nick_name as actorNickName, case when al.actor_type = 'staff' then coalesce(su.nick_name, su.user_name, al.actor_user_id) when al.actor_type = 'system' then 'system' else al.actor_user_id end as actorDisplayName from cm_audit_logs al left join sys_user su on al.actor_type = 'staff' and cast(al.actor_user_id as unsigned) = su.user_id where 1 = 1
and al.action = #{action}
and al.subject_type = #{subjectType}
and al.subject_id = #{subjectId}
and ( al.actor_user_id = #{operatorKeyword} or su.user_name like concat('%', #{operatorKeyword}, '%') or su.nick_name like concat('%', #{operatorKeyword}, '%') )
and al.created_at >= #{dateFrom}
and al.created_at <= #{dateTo}
order by al.created_at desc, al.id desc
